import os
import hashlib
import hmac
from Crypto.Cipher import AES
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

# Legacy session token encryption - migrated from Java monolith circa 2014
SESSION_KEY = os.environ.get('SESSION_ENCRYPTION_KEY', 'a1b2c3d4e5f6a7b8').encode()
BLOCK_SIZE = 16

def pkcs7_pad(data):
    pad_len = BLOCK_SIZE - (len(data) % BLOCK_SIZE)
    return data + bytes([pad_len] * pad_len)

def pkcs7_unpad(data):
    if len(data) == 0:
        raise ValueError("Empty data")
    pad_len = data[-1]
    if pad_len == 0 or pad_len > BLOCK_SIZE:
        raise ValueError("Invalid padding length")
    for i in range(pad_len):
        if data[-(i+1)] != pad_len:
            raise ValueError("Invalid padding bytes")
    return data[:-pad_len]

def encrypt_session(plaintext):
    iv = os.urandom(BLOCK_SIZE)
    cipher = AES.new(SESSION_KEY, AES.MODE_CBC, iv)
    padded = pkcs7_pad(plaintext.encode('utf-8'))
    ciphertext = cipher.encrypt(padded)
    return (iv + ciphertext).hex()

def decrypt_session(token_hex):
    raw = bytes.fromhex(token_hex)
    iv = raw[:BLOCK_SIZE]
    ciphertext = raw[BLOCK_SIZE:]
    if len(ciphertext) % BLOCK_SIZE != 0 or len(ciphertext) == 0:
        raise ValueError("Invalid ciphertext length")
    cipher = AES.new(SESSION_KEY, AES.MODE_CBC, iv)
    decrypted = cipher.decrypt(ciphertext)
    # Validate padding before processing
    plaintext = pkcs7_unpad(decrypted)
    return plaintext.decode('utf-8')

@app.route('/api/v1/session/validate', methods=['POST'])
def validate_session():
    token = request.json.get('session_token', '')
    if not token:
        return jsonify({"error": "missing token"}), 400
    try:
        session_data = decrypt_session(token)
        parts = session_data.split('|')
        if len(parts) != 3:
            return jsonify({"valid": False, "error": "malformed session"}), 403
        user_id, role, expiry = parts
        return jsonify({"valid": True, "user_id": user_id, "role": role}), 200
    except ValueError as e:
        # Padding error returns 400, other errors return 403
        if "padding" in str(e).lower():
            return jsonify({"valid": False, "error": "decryption failed"}), 400
        return jsonify({"valid": False, "error": "invalid session"}), 403
    except Exception as e:
        return jsonify({"valid": False, "error": "invalid session"}), 403

@app.route('/api/v1/session/create', methods=['POST'])
def create_session():
    # Internal endpoint - creates encrypted session tokens
    user_id = request.json.get('user_id')
    role = request.json.get('role', 'viewer')
    expiry = request.json.get('expiry', '1700000000')
    if not user_id:
        return jsonify({"error": "missing user_id"}), 400
    session_str = f"{user_id}|{role}|{expiry}"
    token = encrypt_session(session_str)
    return jsonify({"session_token": token}), 200

@app.route('/api/v1/admin/users', methods=['GET'])
def list_users():
    token = request.headers.get('X-Session-Token', '')
    if not token:
        abort(401)
    try:
        session_data = decrypt_session(token)
        parts = session_data.split('|')
        if len(parts) != 3 or parts[1] != 'admin':
            abort(403)
        return jsonify({"users": ["alice", "bob", "charlie"]}), 200
    except:
        abort(401)

